-- koloni-150: kural kaynakları (yalnız yönetici okur/yazar) + ses_siniflari.durum
alter table public.ses_siniflari add column if not exists durum text;
update public.ses_siniflari set durum = case when kaynak_zayif then 'kaynak zayıf · KİLİTLİ' else 'teyitli · KİLİTLİ' end;
create table if not exists public.kural_kaynaklari (
  id text primary key, grup text not null, sira int not null default 0, ad text not null,
  degerler text, seviye text, aciklama text, kaynak text, durum text, updated_at timestamptz default now());
alter table public.kural_kaynaklari enable row level security;
revoke all on public.kural_kaynaklari from anon;
grant select, insert, update on public.kural_kaynaklari to authenticated;
drop policy if exists kural_kaynaklari_admin on public.kural_kaynaklari;
create policy kural_kaynaklari_admin on public.kural_kaynaklari for all to authenticated using (public.sa_is_admin()) with check (public.sa_is_admin());
on conflict (id) do update set grup=excluded.grup, sira=excluded.sira, ad=excluded.ad, degerler=excluded.degerler, seviye=excluded.seviye, aciklama=excluded.aciklama, kaynak=excluded.kaynak, durum=excluded.durum, updated_at=now();
