insert into public.kural_kaynaklari (id,grup,sira,ad,degerler,seviye,aciklama,kaynak,durum) values
('ors_formul','oğul skoru','1','Oğul Risk Skoru formülü','Genetik×0,30 + Sıkışıklık×0,40 + Mevsim×0,15 + Ana yaşı×0,15; anasız ≤5, 120 günde oğul verdi ≤15','—','Ağırlıklı toplam (0–100)','—','uzman tahmini'),
('ors_bypass','oğul skoru','2','Ötme bypass','400–500 Hz ritmik ≥1 dk → skor 100 (Kritik); oğul yüksüğü de bypass','kritik','Yeni çıkan ana ötmesi oğul/ikinci oğul hazırlığını gösterir','Michelsen A., Kirchner W.H., Andersen B.B., Lindauer M. (1986). J Comp Physiol A 158:605–611 · Ramsey M.-T., Bencsik M., Newton M.I. ve ark. (2020). Scientific Reports 10, doi:10.1038/s41598-020-66115-5','KİLİTLİ'),
('ors_genetik','oğul skoru','3','Genetik bileşen','Irk/melez tablosu (0–100)','—','Irkın oğul eğilimi','Kullanıcı tablosu','KİLİTLİ'),
('ors_mevsim','oğul skoru','4','Mevsim bileşeni','Oğul dönemi zirvesi 100, aksi 50; canlı nektar akımı → 100','—','Bölge profiline göre dönem','—','uzman tahmini'),
('ors_anayasi','oğul skoru','5','Ana yaşı bileşeni','Bu yıl 20 · 1 yaş 60 · ≥2 yaş 100 · bilinmiyor 60','—','Yaşlı ana oğul eğilimini artırır','—','uzman tahmini'),
('ors_sik_manuel','oğul skoru','6','Sıkışıklık (sensörsüz)','Dolu çerçeve / kapasite ×100; yer «dolu» 100, «dolmak» 75, bilinmiyor 50','—','Muayene verisinden','—','uzman tahmini'),
('ors_sik_sensor','oğul skoru','7','Sıkışıklık Puanı (sensörlü)','Puan = Σ(kat×w)/Σ(w bağlı sensörler)×100; w: Tartı 30 · IR 25 · Ses+titreşim 20 · Isı 15 · Nem 10; her kat 0–1','—','Eksik sensörün payı orantılı dağıtılır; sensör yoksa manuel kural','—','uzman tahmini · KİLİTLİ'),
('sik_tarti','oğul skoru','8','Tartı katı (w 30)','(kütle − kutu×8 kg)/kutu/30 kg, 0–1; artış ancak IR veya Nem katı ≥0,5 ise sayılır (bal akımı koruması)','—','Kat sayısıyla filtrelenmiş kütle','—','uzman tahmini'),
('sik_ir','oğul skoru','9','IR katı (w 25)','(son/ortanca − 1)/0,5, 0–1','—','Giriş trafiği/toplanma; kovanın kendi ortancası','—','uzman tahmini'),
('sik_ses','oğul skoru','10','Ses+titreşim katı (w 20)','(son dB − ortanca dB)/6, 0–1','—','Kovanın kendi tabanından sapma','Ferrari S., Silva M., Guarino M., Berckmans D. (2008). Computers and Electronics in Agriculture 64:72–77','uzman tahmini'),
('sik_isi','oğul skoru','11','Isı katı (w 15)','≤35,5 °C → 0; 35,5–36 doğrusal; ≥36 °C → 1','—','Kuluçka ısısının üst sınırı aşması','Ferrari S., Silva M., Guarino M., Berckmans D. (2008). Computers and Electronics in Agriculture 64:72–77','uzman tahmini'),
('sik_nem','oğul skoru','12','Nem katı (w 10)','(son − ortanca)/15 %RH, 0–1; dış nem ≥%85 veya yağmur okuması yok sayılır','—','Hava etkisi filtreli','Ferrari S., Silva M., Guarino M., Berckmans D. (2008). Computers and Electronics in Agriculture 64:72–77','uzman tahmini'),
('m1_yuksuk','muayene','20','Yüksük türü','Boş kupa → sayılmaz · 1–2 yüksük + ana var (sessiz değiştirme) → bypass yok · çok yüksük + ana var (oğul) → bypass · çok yüksük + ana yok (acil) → anasız (≤5)','yuksek','Yüksük türü oğul riskini belirler','Winston M.L. (1987). The Biology of the Honey Bee. Harvard University Press (kitap) · Fell R.D., Morse R.A. (1984). Emergency queen cell production in the honey bee colony. Insectes Sociaux 31(3):221–237','teyitli'),
('m2_anasiz','muayene','21','Anasızlık: ses + yumurta/yüksük','Anasızlık sesi + yumurta yok → Yüksek «Anasızlık güçlü»; yumurta, larva ve yüksük yok → «ana ver veya birleştir»','yuksek','Ana kaybı 6–12 saatte fark edilir, acil yüksükler 12–48 saatte <3 günlük larvadan başlar','Fell R.D., Morse R.A. (1984). Emergency queen cell production in the honey bee colony. Insectes Sociaux 31(3):221–237 · Hatch S., Tarpy D.R., Fletcher D.J.C. (1999). Insectes Sociaux 46(4):372–377','teyitli'),
('m3_yalanci','muayene','22','Yalancı ana / erkek yumurtlayan ana','Gözde çok yumurta + ana görülmedi → yalancı ana şüphesi; dağınık erkek yavru + ana var → erkek yumurtlayan ana; 9 gün sonra kapalı yavru kontrolü','yuksek','Anasız kolonide işçiler erkek gözlerine yumurtlar, eşzamanlı erkek yavru üretir','Page R.E., Erickson E.H. (1988). Reproduction by worker honey bees. Behav Ecol Sociobiol 23:117–126','teyitli (gözde çok yumurta bulgusu uygulamaya dayalı)'),
('m4_takvim','muayene','23','Yüksük takvimi / ikinci oğul','Kapanma ~8,8 gün (7–12), çıkış kapanmadan ~7,2 gün sonra (toplam ~15,7 gün); ilk oğuldan 4–7 gün sonra ötme, ikinci oğul riski','erken','Kontrol günü önerisi','Tofilski A., Czekońska K. (2004). Emergency queen rearing in honeybee colonies with brood of known age. Apidologie 35(3):275–282 · Winston M.L. (1980). Swarming, afterswarming, and reproductive rate of unmanaged honeybee colonies. Insectes Sociaux 27:391–398 · Ramsey M.-T., Bencsik M., Newton M.I. ve ark. (2020). Scientific Reports 10, doi:10.1038/s41598-020-66115-5','teyitli'),
('m5_belirti','muayene','24','Genç arı salkımı / yumurtlama azaldı','EKLENMEDİ','—','Pierce 2007: anaya daha az yem verilir ama oğul öncesi ana ~1 yumurta/dk yumurtlamaya devam eder → çelişkili; salkım için hakemli ölçüt bulunamadı','Pierce A.L., Lewis L.A., Schneider S.S. (2007). Ethology 113:267–275','teyitsiz — eklenmedi'),
('m6_muayene_filtre','muayene','25','Kapak açma sonrası ses filtresi','EKLENMEDİ','—','Hakemli kaynak bulunamadı','—','teyitsiz — eklenmedi'),
('m7_ogul_sonrasi','muayene','26','Oğul sonrası ses düşüşü','Oğul anı sesinden sonraki 3 saatte uğultu tabana göre ≥6 dB düşerse → bilgi «Oğul çıkmış olabilir — kontrol et»','bilgi','Başarılı oğul çıkışında titreşim/uğultu belirgin düşer, ötme kesilir','Ramsey M.-T., Bencsik M., Newton M.I. ve ark. (2020). Scientific Reports 10, doi:10.1038/s41598-020-66115-5','teyitli'),
('m8_yuksuk_kirma','muayene','27','«Yüksük kırmak oğulu durdurmaz» metni','EKLENMEDİ','—','Hakemli deneysel kaynak bulunamadı (arıcı deneyimi)','—','teyitsiz — eklenmedi')
